import subprocess,re,glob
branches=['rachel','monica','phoebe','joey','chandler','ross']
commits=set()
for b in branches:
    for sha in subprocess.check_output(['git','rev-list',f'origin/friend/{b}'],text=True).split():
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
        if re.search(r'^Friend-Message:\s*1\s*$', msg, re.M):
            commits.add(sha)
recorded=set()
for path in glob.glob('S*/E*.md'):
    recorded.update(re.findall(r'^Source: friend/\w+ @ ([0-9a-f]{40})', open(path).read(), re.M))
extra=recorded-commits
print("extra recorded:", len(extra))
for s in list(extra)[:20]: print(s)
